Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await FortunePrefs.load();
  runApp(MaterialApp(
    debugShowCheckedModeBanner: false,
    theme: SeniorTheme.themeData,
    // 휴대폰 너비(400)로 가운데에 보여 준다
    builder: (context, child) => ColoredBox(
      color: const Color(0xFF333333),
      child: Center(child: SizedBox(width: 400, child: child)),
    ),
    home: Builder(
      builder: (context) => Scaffold(
        appBar: AppBar(title: const Text('어르신 알리미 (미리 보기)')),
        body: Column(
          children: [
            FortuneCard(loadToday: () async => _day(_today)),
            Padding(
              padding: const EdgeInsets.all(16),
              child: ElevatedButton(
                onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => _screen())),
                child: const Text('운세 화면 열기'),
              ),
            ),
          ],
        ),
      ),
    ),
  ));
}

Widget _screen() => FortuneScreen(
      loadToday: () async => _day(_today),
      loadTomorrow: () async => _day(_tomorrow),
      loadNoticeCount: () async => 3,
      requestPermission: () async => true,
      adsEnabled: false,
    );
